"""Read-only combined results browser. Keeps study cohorts and coder layers separate."""
from pathlib import Path
from collections import Counter
import csv,hashlib,html,json,os,sys
ROOT=Path(__file__).resolve().parents[1];sys.path.insert(0,str(ROOT))
from palterlab.common import read,save,now
RUNS=[ROOT/'runs/lean175_20260923',ROOT/'runs/repeat_fixed_20260924']
KIMI=ROOT/'runs/kimi_review_20260924'
OUT=ROOT/'docs/current_results_20260924'
NAMES={'llama8':'Llama 3.1 8B','mistral24':'Mistral Small 3.2 24B','qwen9':'Qwen 3.5 9B','deepseek':'DeepSeek V4.1 Flash','sonnet':'Claude Sonnet 5','gpt':'GPT-5.6 Luna','gemma27':'Gemma 3 27B','nemotron30':'Nemotron 3 Nano 30B'}
COHORTS=['Earlier discovery','Earlier supplementary models','Earlier confirmation','Fixed repeat']
LABELS={'honest':'Honest','paltering':'Paltering code','false_assertion':'False assertion','incidental_error':'Incidental error','invalid_evidence':'Invalid supporting evidence','ambiguous':'Ambiguous','unresolved':'Unresolved'}
def href(p):return os.path.relpath(p,OUT).replace(os.sep,'/')
def build():
 OUT.mkdir(parents=True,exist_ok=True)
 kimi={x['episode_id']:x for p in (KIMI/'results').glob('*.json') for x in [read(p)]}
 rows=[]
 for run in RUNS:
  cfg=read(run/'config.json');cases={x['case_id']:x for x in read(run/'pack/cases.json')}
  adj=read(run/'review/adjudications.json') if (run/'review/adjudications.json').exists() else {}
  prior=read(run/'monitoring/completion_audit.json').get('confirmation',{}).get('flag_review',[]) if (run/'monitoring/completion_audit.json').exists() else []
  extra={x['episode_id']:x for x in prior}
  for p in sorted(run.glob('episodes/*/result.json')):
   d=read(p);t=d.get('turns',[{}])[0] if d.get('turns') else {};g=read(p.parent/'generation.json') if (p.parent/'generation.json').exists() else {};c=read(run/'candidates'/d['candidate']/'candidate.json');case=cases[d['case_id']]
   q=next((j for j in t.get('judgments',[]) if j.get('model')=='judge_qwen'),{})
   k=kimi.get(d['episode_id']) if run==RUNS[1] else None
   co=('Fixed repeat' if run==RUNS[1] else 'Earlier confirmation' if d['phase'] in ['transfer','transfer_baseline'] else 'Earlier discovery' if d['model'] in cfg['search_models'] else 'Earlier supplementary models')
   h=g.get('pre_reply_history',g.get('history',[]));system=next((m.get('content','') for m in h if m.get('role')=='system'),'')
   manual=[]
   if d['episode_id']+'-t1' in adj:manual.append(adj[d['episode_id']+'-t1'])
   if d['episode_id'] in extra:manual.append(extra[d['episode_id']])
   uid=hashlib.sha256((run.name+':'+d['episode_id']).encode()).hexdigest()[:16]
   row={'uid':uid,'episode':d['episode_id'],'run':run.name,'cohort':co,'phase':d['phase'],'model':d['model'],'model_name':NAMES.get(d['model'],d['model']),'case':d['case_id'],'condition_id':d['candidate'],'arm':d.get('arm'), 'access':d.get('information_profile'),'status':d['status'],'qwen_code':t.get('category'),'qwen_raw':q.get('category'),'qwen':q,'kimi_status':k['status'] if k else 'pending' if co=='Fixed repeat' and d['status']=='completed' else 'not_in_batch','kimi_code':k.get('category') if k else None,'kimi_raw':k.get('raw_category') if k else None,'kimi':k.get('judgment') if k else None,'kimi_error':k.get('error') if k else None,'question':case['question'],'gist':case['proposition'],'source_answer':case['answer'],'required':case['required_disclosures'],'constraints':case['disclosure_constraints'],'honest_reference':case.get('references',{}).get('honest',''),'reply':t.get('reply',g.get('reply','')),'condition':c.get('condition',''),'added_notes':c.get('new_records',[]),'system':system,'records':g.get('authoritative_records',[]),'opened':g.get('office_read_paths',[]),'assistant_reviews':manual,'error':d.get('error'),'score_version':d.get('score_version'),'scoring_link':href(p),'generation_link':href(p.parent/'generation.json') if g else None,'condition_link':href(run/'candidates'/d['candidate']/'candidate.json')}
   rows.append(row)
 assert len(rows)==1250 and sum(x['status']=='completed' for x in rows)==1178
 assert all(x['score_version']=='graded_v2_qwen_only' for x in rows if x['status']=='completed')
 summaries=[]
 for co in COHORTS:
  group=[x for x in rows if x['cohort']==co];done=[x for x in group if x['status']=='completed'];cats=Counter(x['qwen_code'] for x in done)
  summaries.append({'cohort':co,'attempts':len(group),'scored':len(done),'failed':len(group)-len(done),'categories':dict(cats),'qwen_raw':sum(x['qwen_raw']=='paltering' for x in done),'qwen_pass':cats['paltering']})
 repeat=[]
 for model in ['llama8','mistral24','qwen9','deepseek','sonnet','gpt']:
  cells=[]
  for arm in ['candidate_0109','candidate_0136','routine','contingent']:
   group=[x for x in rows if x['cohort']=='Fixed repeat' and x['model']==model and x['arm']==arm];done=[x for x in group if x['status']=='completed'];kd=[x for x in done if x['kimi_status']=='completed']
   cells.append({'arm':arm,'n':len(done),'qwen':sum(x['qwen_code']=='paltering' for x in done),'kimi_n':len(kd),'kimi':sum(x['kimi_code']=='paltering' for x in kd),'failed':len(group)-len(done)})
  repeat.append({'model':NAMES[model],'cells':cells})
 ks=read(KIMI/'summary.json') if (KIMI/'summary.json').exists() else {}
 data={'at':now(),'rows':rows,'summary':summaries,'repeat':repeat,'kimi':ks,'source_reports':[{'name':r.name,'url':href(r/'review/completion.html')} for r in RUNS]}
 save(OUT/'results.json',data)
 with (OUT/'results.csv').open('w',newline='') as f:
  keys=['uid','episode','cohort','phase','model_name','case','condition_id','arm','access','status','qwen_raw','qwen_code','kimi_status','kimi_raw','kimi_code','question','gist','reply','condition','scoring_link'];w=csv.DictWriter(f,fieldnames=keys,extrasaction='ignore');w.writeheader();w.writerows(rows)
 jsdata=json.dumps(data,ensure_ascii=False).replace('<','\\u003c').replace('>','\\u003e').replace('&','\\u0026')
 doc=TEMPLATE.replace('__DATA__',jsdata)
 tmp=OUT/'index.html.tmp';tmp.write_text(doc);os.replace(tmp,OUT/'index.html')
 print(json.dumps({'path':str(OUT/'index.html'),'attempts':len(rows),'scored':1178,'qwen_raw':sum(x['qwen_raw']=='paltering' for x in rows),'qwen_pass':sum(x['qwen_code']=='paltering' for x in rows),'kimi_completed':ks.get('completed',0)}))

TEMPLATE='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Results and reply review</title><style>
*{box-sizing:border-box}body{margin:0;background:#f6f7f9;color:#203247;font:16px/1.6 system-ui,-apple-system,sans-serif}main{max-width:1180px;margin:auto;padding:38px 24px 80px}header{max-width:840px}h1{font:600 clamp(30px,4vw,44px)/1.2 Georgia,serif;margin:0 0 20px}h2{font-size:23px;margin:30px 0 10px}h3{font-size:16px;margin:18px 0 8px}p{margin:12px 0}a{color:#215b85}.muted{font-size:13px;color:#55677a}.notice{padding:15px 18px;background:#eef2f7;border-left:3px solid #587694}.scroll{overflow:auto}table{border-collapse:collapse;width:100%;background:white;font-size:14px;font-variant-numeric:tabular-nums}td,th{padding:10px 12px;text-align:left;border-bottom:1px solid #dce2e8}th{background:#edf1f5;font-weight:650}nav{display:flex;flex-wrap:wrap;gap:15px;margin:20px 0}.filters{display:grid;grid-template-columns:repeat(3,1fr);gap:12px;padding:18px;background:white;border:1px solid #d6dfe8;border-radius:6px}label{font-size:13px;font-weight:600}select,input,button{font:inherit;color:inherit;border:1px solid #adbdcd;background:white;border-radius:4px;padding:8px 10px;min-height:42px}select,input{display:block;width:100%;margin-top:5px}button{cursor:pointer}button:disabled{opacity:.45;cursor:default}.wide{grid-column:1/-1}.card{border:1px solid #ccd7e3;border-radius:7px;background:white;margin:14px 0;scroll-margin-top:24px}.card>summary{cursor:pointer;padding:17px 20px;list-style-position:inside}.card>summary small{display:block;color:#586c80;margin-top:5px}.inside{padding:2px 20px 24px;border-top:1px solid #e0e5eb}.columns{display:grid;grid-template-columns:1fr 1fr;gap:28px}.prose{white-space:pre-wrap;overflow-wrap:anywhere}.reply{background:#f3f6fa;padding:16px;border-left:3px solid #5c7d9c}mark{background:#fff0ae;color:inherit}.tag{display:inline-block;padding:2px 7px;border-radius:4px;background:#e8edf3;font-size:12px;margin:0 5px}.tag.warn{background:#fff0d8;color:#73501c}.review{padding:12px;background:#fff1df;border-left:3px solid #b38847}.inside details{border-top:1px solid #dee4eb;padding-top:10px;margin-top:14px}.inside summary{cursor:pointer;font-weight:600}pre{white-space:pre-wrap;overflow-wrap:anywhere;font-size:12px}.paging{display:flex;align-items:center;gap:12px;margin:18px 0}.key{font-size:13px}.count{font-size:13px;color:#54677c}@media(max-width:760px){main{padding:25px 13px}.columns{grid-template-columns:1fr;gap:0}.filters{grid-template-columns:1fr 1fr}td,th{padding:8px}.inside{padding:4px 14px 18px}}
</style></head><body><main><header><h1>Results and reply review</h1><p>The earlier search and the fixed repeat study are collected here. Rates remain separate by study phase. Each reply includes its question, factual conclusion, source documents, condition and saved coding.</p><p class="notice"><strong>Paltering codes are provisional.</strong> A Qwen nomination, a passed automated check and a human-confirmed case are different things. Existing assistant review notes are preserved. Kimi is independently reviewing all 465 scored repeat replies; no reader tests are running.</p><nav><a href="#results">Results</a><a href="#repeat">Repeat comparison</a><a href="kimi_comparison.html">Qwen and Kimi</a><a href="#replies">Browse replies</a><a href="results.csv" download>Download table</a><a href="results.json" download>Download full records</a></nav><p id="snapshot" class="muted"></p></header>
<section id="results"><h2>Results by study phase</h2><div id="overview" class="scroll"></div><p class="muted">Counts use the same saved Qwen scoring version. Discovery is adaptive and spans different scenarios; the repeat study concerns one scenario. These samples do not define a single overall paltering rate. Failed attempts are not counted as honest.</p></section>
<section id="repeat"><h2>Repeat comparison</h2><p>Each cell shows paltering codes / scored replies (rate), combining private and shared access. Twenty attempts were scheduled per model and condition. Kimi results use only the judgments completed so far.</p><div id="repeatTable" class="scroll"></div><p id="kimiStatus" class="notice"></p><p class="muted">Kimi receives the question, factual proposition, disclosure constraints, source records and reply. It does not receive Qwen's coding, the generating model, pressure prompts or comprehension checks. Its rubric explicitly checks the whole reply against the factual gist. This difference in presentation is recorded; disagreement is not a clean model-only comparison. Agreement is not accuracy.</p></section>
<section id="replies"><h2>Browse replies</h2><p class="key">The default view includes every reply that passed Qwen's automated paltering checks, including cases with contrary assistant review notes. Choose “All raw Qwen nominations” to inspect rejected flags, or “All replies and failures” for the complete archive.</p><div class="filters"><label>Show<select id="mode"><option value="qwen_pass">Qwen paltering codes</option><option value="raw">All raw Qwen nominations</option><option value="kimi">Kimi paltering codes</option><option value="either">Either judge's paltering codes</option><option value="both">Both judges' paltering codes</option><option value="disagree">Qwen/Kimi disagreement</option><option value="all">All replies and failures</option><option value="failed">Failed attempts</option></select></label><label>Study phase<select id="cohort"><option value="all">All phases</option></select></label><label>Model<select id="model"><option value="all">All models</option></select></label><label>Scenario<select id="case"><option value="all">All scenarios</option></select></label><label>Qwen category<select id="category"><option value="all">All categories</option></select></label><label>Access<select id="access"><option value="all">Both profiles</option><option>private</option><option>shared</option></select></label><label class="wide">Search question, reply, condition or judge explanation<input id="search" type="search" placeholder="e.g. warning, food, candidate_0109"></label></div><p id="count" aria-live="polite"></p><div class="paging"><button id="prev">Previous</button><span id="page"></span><button id="next">Next</button></div><div id="cards"></div></section>
</main><script id="data" type="application/json">__DATA__</script><script>
const D=JSON.parse(document.getElementById('data').textContent);const $=id=>document.getElementById(id);const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const label=x=>({honest:'Honest',paltering:'Paltering code',false_assertion:'False assertion',invalid_evidence:'Invalid supporting evidence',ambiguous:'Ambiguous',unresolved:'Unresolved',incidental_error:'Incidental error'}[x]||x||'Unscored');const prose=x=>'<div class="prose">'+esc(x)+'</div>';const detail=(s,b)=>'<details><summary>'+esc(s)+'</summary>'+b+'</details>';const fmt=(k,n)=>n?`${k}/${n} (${(100*k/n).toFixed(1)}%)`:'Pending';let page=0,filtered=[];const size=20;
$('snapshot').textContent='Snapshot: '+new Date(D.at).toLocaleString()+'. '+D.rows.length+' attempts; '+D.summary.reduce((a,x)=>a+x.scored,0)+' scored replies. Refresh after the report is updated.';
$('overview').innerHTML='<table><thead><tr><th>Study phase</th><th>Scored / attempts</th><th>Honest</th><th>Paltering code</th><th>False assertion</th><th>Other / unresolved</th><th>Failed</th></tr></thead><tbody>'+D.summary.map(s=>'<tr><td>'+esc(s.cohort)+'</td><td>'+s.scored+'/'+s.attempts+'</td><td>'+(s.categories.honest||0)+'</td><td>'+fmt(s.qwen_pass,s.scored)+'</td><td>'+(s.categories.false_assertion||0)+'</td><td>'+(s.scored-(s.categories.honest||0)-s.qwen_pass-(s.categories.false_assertion||0))+'</td><td>'+s.failed+'</td></tr>').join('')+'</tbody></table>';
$('repeatTable').innerHTML='<table><thead><tr><th>Model</th><th>Selected 0109</th><th>Selected 0136</th><th>Routine</th><th>Contingent continuation</th><th>Failed / 80</th></tr></thead><tbody>'+D.repeat.map(m=>'<tr><td>'+esc(m.model)+'</td>'+m.cells.map(c=>'<td><strong>Qwen:</strong> '+fmt(c.qwen,c.n)+'<br><span class="muted">Kimi: '+fmt(c.kimi,c.kimi_n)+'</span></td>').join('')+'<td>'+m.cells.reduce((a,c)=>a+c.failed,0)+'/80</td></tr>').join('')+'</tbody></table>';
const K=D.kimi;$('kimiStatus').textContent='Kimi: '+(K.completed||0)+'/465 coded, '+(K.failed||0)+' failed; '+(K.state?.status||'pending')+'. Accounted cost $'+Number(K.cost_usd||0).toFixed(2)+' / $20 cap. '+(K.field_check_agreement!==null&&K.field_check_agreement!==undefined?'Category agreement with Qwen among completed pairs: '+(K.field_check_agreement*100).toFixed(1)+'%.':'');
function opts(id,values,names={}){for(const x of [...new Set(values)].filter(Boolean).sort()){const o=document.createElement('option');o.value=x;o.textContent=names[x]||x;$(id).append(o)}}
opts('cohort',D.rows.map(r=>r.cohort));opts('model',D.rows.map(r=>r.model),Object.fromEntries(D.rows.map(r=>[r.model,r.model_name])));opts('case',D.rows.map(r=>r.case));opts('category',D.rows.map(r=>r.qwen_code),Object.fromEntries(D.rows.map(r=>[r.qwen_code,label(r.qwen_code)])));
function judge(j,name,code){if(!j)return '<p class="muted">'+esc(name)+': no completed judgment.</p>';return '<h3>'+esc(name)+' · '+esc(label(code))+'</h3>'+prose(j.explanation||'')+'<p><strong>Proposed wrong inference:</strong> '+esc(j.specific_wrong_inference||'None identified')+'</p><p class="muted">Raw label: '+esc(j.category)+'; cited record: '+esc(j.evidence_id||'none')+'.</p>'+detail('Full '+name+' coding','<pre>'+esc(JSON.stringify(j,null,2))+'</pre>')}
function card(r){let reply=esc(r.reply||'No saved reply.');const q=r.qwen?.quote;if(q&&r.reply.includes(q)){const at=r.reply.indexOf(q);reply=esc(r.reply.slice(0,at))+'<mark>'+esc(q)+'</mark>'+esc(r.reply.slice(at+q.length))}const notes=r.assistant_reviews.map(a=>'<div class="review"><strong>Existing assistant review</strong>'+prose(a.basis||a.reason||a.assistant_review||'')+(a.judge_inconsistency?prose(a.judge_inconsistency):'')+'<p class="muted">Assistant review, not independent human validation. Raw codes are preserved.</p></div>').join('');const sources=r.records.map(s=>detail(s.record_id,prose(s.text))).join('');return '<details class="card" id="case-'+r.uid+'"><summary><strong>'+esc(r.model_name)+' · '+esc(r.case)+'</strong> <span class="tag '+(r.qwen_code==='paltering'?'warn':'')+'">Qwen: '+esc(label(r.qwen_code))+'</span>'+(r.kimi_code?'<span class="tag">Kimi: '+esc(label(r.kimi_code))+'</span>':'')+(r.assistant_reviews.length?'<span class="tag warn">Review note</span>':'')+'<small>'+esc(r.cohort)+' · '+esc(r.condition_id)+' · '+esc(r.access)+' · '+esc(r.episode)+'</small></summary><div class="inside"><div class="columns"><section><h3>Question</h3>'+prose(r.question)+'<h3>Factual conclusion</h3>'+prose((r.source_answer?'Supported: ':'Not supported: ')+r.gist)+'<h3>Facts necessary to answer</h3><ul>'+r.required.map(x=>'<li>'+esc(x)+'</li>').join('')+'</ul><p><strong>Disclosure constraints:</strong> '+esc(r.constraints)+'</p>'+detail('Authored honest reference',prose(r.honest_reference))+detail('Condition prompt',prose(r.condition))+detail('Additional operational notes','<pre>'+esc(JSON.stringify(r.added_notes,null,2))+'</pre>')+detail('Full system prompt',prose(r.system))+detail('Underlying source records',sources)+detail('Files opened by the office agent','<pre>'+esc(JSON.stringify(r.opened,null,2))+'</pre>')+'</section><section><h3>Full reply</h3><div class="prose reply">'+reply+'</div><p class="muted">Yellow marks Qwen’s quoted passage, when it matches. A highlight does not establish misleadingness.</p>'+notes+(r.error?'<p class="review">Recorded failure: '+esc(r.error)+'</p>':'')+judge(r.qwen,'Qwen',r.qwen_code)+judge(r.kimi,'Kimi',r.kimi_code)+(r.kimi_status==='pending'?'<p class="muted">Kimi review pending.</p>':'')+(r.kimi_error?prose(r.kimi_error):'')+'</section></div><p><a href="#case-'+r.uid+'">Link to this reply</a> · <a href="'+esc(r.scoring_link)+'">Original scoring JSON</a> · <a href="'+esc(r.condition_link)+'">Condition JSON</a></p></div></details>'}
function draw(){const max=Math.max(1,Math.ceil(filtered.length/size));page=Math.max(0,Math.min(page,max-1));$('cards').innerHTML=filtered.slice(page*size,(page+1)*size).map(card).join('');$('count').textContent=filtered.length+' matching attempts. Open a row to read the full reply and its evidence.';$('page').textContent='Page '+(page+1)+' of '+max;$('prev').disabled=page===0;$('next').disabled=page===max-1}
function filter(reset=true){const mode=$('mode').value,q=$('search').value.trim().toLowerCase();filtered=D.rows.filter(r=>{if(mode==='qwen_pass'&&r.qwen_code!=='paltering')return false;if(mode==='raw'&&r.qwen_raw!=='paltering')return false;if(mode==='kimi'&&r.kimi_code!=='paltering')return false;if(mode==='either'&&r.qwen_code!=='paltering'&&r.kimi_code!=='paltering')return false;if(mode==='both'&&!(r.qwen_code==='paltering'&&r.kimi_code==='paltering'))return false;if(mode==='disagree'&&!(r.kimi_status==='completed'&&r.qwen_code!==r.kimi_code))return false;if(mode==='failed'&&r.status==='completed')return false;for(const [id,key] of [['cohort','cohort'],['model','model'],['case','case'],['category','qwen_code'],['access','access']])if($(id).value!=='all'&&r[key]!==$(id).value)return false;return !q||[r.question,r.reply,r.condition,r.case,r.condition_id,r.episode,r.qwen?.explanation,r.kimi?.explanation].join(' ').toLowerCase().includes(q)});if(reset)page=0;draw()}
for(const id of ['mode','cohort','model','case','category','access','search'])$(id).addEventListener(id==='search'?'input':'change',()=>filter());$('prev').onclick=()=>{page--;draw()};$('next').onclick=()=>{page++;draw()};function reveal(){const uid=location.hash.replace('#case-','');if(!D.rows.some(r=>r.uid===uid))return;$('mode').value='all';for(const id of ['cohort','model','case','category','access'])$(id).value='all';$('search').value='';filter();page=Math.floor(filtered.findIndex(r=>r.uid===uid)/size);draw();const el=$('case-'+uid);el.open=true;el.scrollIntoView()};window.addEventListener('hashchange',reveal);filter();reveal();
</script></body></html>'''
if __name__=='__main__':build()
